#include "fleet/FleetDoctrineSystem.h"
namespace subspace {
bool FleetDoctrineSystem::Register(const FleetDoctrine& d){if(d.id.empty())return false;doctrines_[d.id]=d;return true;}
const FleetDoctrine* FleetDoctrineSystem::Get(const std::string& id) const {auto it=doctrines_.find(id);return it==doctrines_.end()?nullptr:&it->second;}
DoctrineReport FleetDoctrineSystem::Evaluate(const FleetDoctrine& d,const std::vector<FleetMember>& members) const {DoctrineReport r;if(members.empty()){r.valid=false;r.warnings.push_back("fleet empty");return r;}double combat=0,support=0,industrial=0;for(auto& m:members){if(!m.isActive)continue;switch(m.role){case FleetRole::Combat:case FleetRole::Flagship:combat++;break;case FleetRole::Support:support++;break;case FleetRole::Mining:case FleetRole::Trading:industrial++;break;default:break;}}double n=combat+support+industrial;if(n<=0){r.valid=false;r.warnings.push_back("no active doctrine ships");return r;}r.combatFraction=combat/n;r.supportFraction=support/n;r.industrialFraction=industrial/n;if(r.combatFraction+0.001<d.desiredCombatFraction){r.valid=false;r.warnings.push_back("combat coverage low");}if(r.supportFraction+0.001<d.desiredSupportFraction){r.valid=false;r.warnings.push_back("support coverage low");}if(r.industrialFraction+0.001<d.desiredIndustrialFraction){r.warnings.push_back("industrial coverage low");}return r;}
}
